<template><view class="m2-page"><view class="m2-heading"><text>我的消息</text><text class="m2-link" @click="refresh">刷新</text></view><view v-for="n in items" :key="n.id" class="m2-card" @click="read(n)"><view class="m2-heading"><text>{{n.title}}</text><text v-if="!n.read" class="dot">未读</text></view><text class="m2-body">{{n.content}}</text><text class="m2-muted">{{date(n.createTime)}}{{n.read?' · 已读':''}}</text></view><view v-if="!items.length&&!loading&&!error" class="m2-empty">暂时没有消息。订阅成功通知将稍后送达。</view><text class="m2-error" v-if="error">{{error}}</text><view v-if="loading||items.length<total" class="m2-link m2-center" @click="load">{{loading?'加载中…':'加载更多'}}</view></view></template>
<script>
import {getNotifications,readNotification} from '../../api/vip'
import {requireLogin} from '../../utils/auth'
export default{data(){return{items:[],page:1,total:0,loading:false,error:''}},onShow(){if(requireLogin())this.refresh()},methods:{date(v){return(v||'').replace('T',' ').slice(0,16)},refresh(){if(this.loading)return;this.items=[];this.page=1;this.total=0;this.load()},async load(){if(this.loading)return;this.loading=true;this.error='';try{const d=await getNotifications({pageNum:this.page,pageSize:20});this.items.push(...d.records);this.total=Number(d.total);this.page++}catch(e){this.error=e.msg}finally{this.loading=false}},async read(n){if(n.read)return;try{await readNotification(n.id);n.read=true}catch(e){this.error=e.msg}}}}
</script><style scoped>.dot{font-size:20rpx;color:#b5533d;border-radius:20rpx;background:#fff0e9;padding:6rpx 14rpx}</style>
